-- AdoptAI schema for Supabase SQL Editor.
-- Safe to run more than once. Creates auth, lots, bids, deals, chats.
-- After it finishes, reload https://neurohh.ru and register again if this database was empty.

create table if not exists _migrations (name text primary key, applied_at timestamptz not null default now());

-- Better Auth schema (identity + sessions for "Sign in with Grok").
--
-- Generated by the Better Auth CLI for its Postgres adapter — DO NOT EDIT by
-- hand. `@/lib/auth/server` runs Better Auth against these tables when
-- DATABASE_URL is set. The columns are camelCase and MUST stay double-quoted so
-- Postgres preserves the case Better Auth queries by.
--
-- Migrations in this folder are the single source of truth for your schema. They
-- apply to Neon during the Vercel build (`npm run build`) and to the local
-- PGLite fallback automatically on startup, so dev matches production. Applied
-- files are recorded by name in `_migrations` and NEVER run again.
--
-- Put YOUR app's schema in NEW ordered files (0002_*.sql, 0003_*.sql, …), never
-- in this one. For app tables, prefer snake_case and give per-user tables a
-- `user_id TEXT NOT NULL` column (TEXT, not UUID — the preview dev user id is
-- the string 'dev-user'), then scope every query to the authenticated user
-- server-side (see the `neon` + `auth` skills and src/lib/auth/verify.server.ts).

create table if not exists "user" (
  "id" text not null primary key,
  "name" text not null,
  "email" text not null unique,
  "emailVerified" boolean not null,
  "image" text,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz default CURRENT_TIMESTAMP not null
);

create table if not exists "session" (
  "id" text not null primary key,
  "expiresAt" timestamptz not null,
  "token" text not null unique,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz not null,
  "ipAddress" text,
  "userAgent" text,
  "userId" text not null references "user" ("id") on delete cascade
);

create table if not exists "account" (
  "id" text not null primary key,
  "accountId" text not null,
  "providerId" text not null,
  "userId" text not null references "user" ("id") on delete cascade,
  "accessToken" text,
  "refreshToken" text,
  "idToken" text,
  "accessTokenExpiresAt" timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  "scope" text,
  "password" text,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz not null
);

create table if not exists "verification" (
  "id" text not null primary key,
  "identifier" text not null,
  "value" text not null,
  "expiresAt" timestamptz not null,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz default CURRENT_TIMESTAMP not null
);

create index if not exists "session_userId_idx" on "session" ("userId");
create index if not exists "account_userId_idx" on "account" ("userId");
create index if not exists "verification_identifier_idx" on "verification" ("identifier");
-- GLYPH adopt marketplace. Per-user rows key off Better Auth text ids.

create table if not exists profiles (
  user_id text primary key,
  handle text not null unique,
  display_name text not null,
  bio text not null default '',
  is_admin boolean not null default false,
  banned boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists listings (
  id text primary key,
  seller_id text not null references profiles (user_id),
  title text not null,
  blurb text not null default '',
  private_description text not null default '',
  kind text not null,
  price integer not null,
  buy_now integer,
  anti_snipe_minutes integer not null default 3,
  ends_at timestamptz,
  status text not null,
  current_bid integer,
  current_bidder_id text,
  bid_count integer not null default 0,
  winner_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint listings_kind_chk check (kind in ('fixed', 'auction')),
  constraint listings_status_chk check (status in ('active', 'sold', 'ended', 'removed')),
  constraint listings_price_chk check (price > 0),
  constraint listings_buynow_chk check (buy_now is null or buy_now > price)
);

create index if not exists listings_feed_idx on listings (status, created_at desc);
create index if not exists listings_seller_idx on listings (seller_id);

create table if not exists tags (
  id serial primary key,
  slug text not null unique,
  label text not null
);

create table if not exists listing_tags (
  listing_id text not null references listings (id) on delete cascade,
  tag_id integer not null references tags (id),
  primary key (listing_id, tag_id)
);

create index if not exists listing_tags_tag_idx on listing_tags (tag_id);

create table if not exists media (
  id text primary key,
  listing_id text not null references listings (id) on delete cascade,
  kind text not null,
  filename text not null,
  mime text not null,
  data_b64 text not null,
  width integer,
  height integer,
  size_bytes integer not null,
  created_at timestamptz not null default now(),
  constraint media_kind_chk check (kind in ('preview', 'file'))
);

create index if not exists media_listing_idx on media (listing_id, kind);

create table if not exists bids (
  id text primary key,
  listing_id text not null references listings (id) on delete cascade,
  bidder_id text not null references profiles (user_id),
  amount integer not null,
  created_at timestamptz not null default now()
);

create index if not exists bids_listing_idx on bids (listing_id, created_at desc);

create table if not exists deals (
  id text primary key,
  listing_id text not null unique references listings (id),
  seller_id text not null references profiles (user_id),
  buyer_id text not null references profiles (user_id),
  amount integer not null,
  status text not null,
  seller_confirmed_at timestamptz,
  buyer_confirmed_at timestamptz,
  files_released_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  constraint deals_status_chk check (
    status in ('awaiting_payment', 'confirmed', 'files_released', 'completed')
  )
);

create index if not exists deals_seller_idx on deals (seller_id, created_at desc);
create index if not exists deals_buyer_idx on deals (buyer_id, created_at desc);

create table if not exists messages (
  id text primary key,
  deal_id text not null references deals (id) on delete cascade,
  sender_id text not null,
  body text not null,
  created_at timestamptz not null default now()
);

create index if not exists messages_deal_idx on messages (deal_id, created_at);

create table if not exists notifications (
  id text primary key,
  user_id text not null,
  kind text not null,
  title text not null,
  body text not null,
  href text not null,
  read_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists notifications_user_idx on notifications (user_id, created_at desc);

create table if not exists reports (
  id text primary key,
  reporter_id text not null references profiles (user_id),
  listing_id text,
  reason text not null,
  status text not null default 'open',
  created_at timestamptz not null default now(),
  constraint reports_status_chk check (status in ('open', 'dismissed', 'actioned'))
);

create index if not exists reports_status_idx on reports (status, created_at desc);
-- Roles (user / moderator / admin) and profile comments.

alter table profiles add column if not exists role text not null default 'user';

update profiles set role = 'admin' where is_admin = true and role = 'user';

alter table profiles drop constraint if exists profiles_role_chk;
alter table profiles add constraint profiles_role_chk check (role in ('user', 'moderator', 'admin'));

create table if not exists profile_comments (
  id text primary key,
  profile_id text not null references profiles (user_id) on delete cascade,
  author_id text not null references profiles (user_id) on delete cascade,
  body text not null,
  created_at timestamptz not null default now(),
  constraint profile_comments_body_chk check (char_length(body) between 1 and 500)
);

create index if not exists profile_comments_profile_idx on profile_comments (profile_id, created_at desc);
-- Public deal numbers (#1001, #1002, …) for participants and moderators.

create sequence if not exists deal_public_no_seq start with 1001;

alter table deals add column if not exists public_no integer;

update deals
set public_no = nextval('deal_public_no_seq')
where public_no is null;

alter table deals alter column public_no set default nextval('deal_public_no_seq');

alter table deals alter column public_no set not null;

create unique index if not exists deals_public_no_idx on deals (public_no);
-- Invite codes and the switch that makes them mandatory for new accounts.

create table if not exists site_settings (
  key text primary key,
  value text not null
);

insert into site_settings (key, value)
values ('require_invite', 'false')
on conflict (key) do nothing;

create table if not exists invite_codes (
  id text primary key,
  code text not null unique,
  created_by text not null references profiles (user_id),
  note text not null default '',
  max_uses integer not null default 1,
  uses integer not null default 0,
  revoked boolean not null default false,
  created_at timestamptz not null default now(),
  constraint invite_max_chk check (max_uses between 1 and 100),
  constraint invite_uses_chk check (uses >= 0 and uses <= max_uses)
);

create table if not exists invite_redemptions (
  id text primary key,
  code_id text not null references invite_codes (id),
  user_id text not null unique,
  created_at timestamptz not null default now()
);
-- Profiles, likes, listing comments, pins, direct chats.

alter table profiles add column if not exists status text not null default 'open';
alter table profiles add column if not exists links jsonb not null default '[]'::jsonb;
alter table profiles add column if not exists badges text[] not null default '{}';

alter table profiles drop constraint if exists profiles_status_chk;
alter table profiles add constraint profiles_status_chk
  check (status in ('open', 'busy', 'closed', 'away'));

create table if not exists profile_images (
  user_id text not null references profiles (user_id) on delete cascade,
  kind text not null,
  mime text not null,
  data_b64 text not null,
  primary key (user_id, kind),
  constraint profile_images_kind_chk check (kind in ('avatar', 'banner', 'background'))
);

alter table listings add column if not exists pinned boolean not null default false;

create table if not exists listing_likes (
  listing_id text not null references listings (id) on delete cascade,
  user_id text not null references profiles (user_id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (listing_id, user_id)
);

create index if not exists listing_likes_listing_idx on listing_likes (listing_id);

create table if not exists listing_comments (
  id text primary key,
  listing_id text not null references listings (id) on delete cascade,
  author_id text not null references profiles (user_id),
  body text not null,
  created_at timestamptz not null default now(),
  constraint listing_comments_body_chk check (char_length(body) between 1 and 500)
);

create index if not exists listing_comments_listing_idx on listing_comments (listing_id, created_at desc);

create table if not exists dm_threads (
  id text primary key,
  low_id text not null references profiles (user_id),
  high_id text not null references profiles (user_id),
  created_at timestamptz not null default now(),
  unique (low_id, high_id),
  constraint dm_threads_order_chk check (low_id < high_id)
);

create table if not exists dm_messages (
  id text primary key,
  thread_id text not null references dm_threads (id) on delete cascade,
  sender_id text not null references profiles (user_id),
  body text not null,
  created_at timestamptz not null default now(),
  constraint dm_messages_body_chk check (char_length(body) between 1 and 2000)
);

create index if not exists dm_messages_thread_idx on dm_messages (thread_id, created_at);
-- Sign-in looks up the lowercased email. Older rows stored the typed case,
-- so the same address then failed as "invalid email or password".
update "user" as u
set email = lower(u.email)
where u.email <> lower(u.email)
  and not exists (
    select 1 from "user" other
    where other.id <> u.id and lower(other.email) = lower(u.email)
  );
-- One-time bridge when Google's OAuth callback is accepted on the Vercel
-- alias but the session cookie must be set on neurohh.ru (__Host- is host-only).
create table if not exists auth_handoff (
  code text primary key,
  cookie_headers text not null,
  expires_at timestamptz not null
);
-- Supabase publishes the public schema through its HTTP API. The app talks to
-- Postgres as the table owner (that role bypasses row level security). The
-- anon and authenticated API roles must not be able to read accounts, lots,
-- bids, or messages if the anon key ever leaks. On a database without those
-- roles (preview, Neon) this is a no-op.

do $$
declare
  r record;
  role_name text;
begin
  for r in
    select c.relname
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p')
  loop
    execute format('alter table public.%I enable row level security', r.relname);
  end loop;

  foreach role_name in array array['anon', 'authenticated']
  loop
    if exists (select 1 from pg_roles where rolname = role_name) then
      execute format('revoke all on all tables in schema public from %I', role_name);
      execute format('revoke all on all sequences in schema public from %I', role_name);
    end if;
  end loop;
end $$;
-- The credential hash is saltHex:keyHex (~161 chars). Keep it as text so a
-- short varchar cannot truncate it into a password that never verifies.
alter table account alter column "password" type text;

-- An empty credential row is what sign-in finds first, so a real hash on a
-- second row never gets checked.
delete from account as empty
where empty."providerId" = 'credential'
  and (empty.password is null or length(empty.password) = 0)
  and exists (
    select 1 from account filled
    where filled."userId" = empty."userId"
      and filled."providerId" = 'credential'
      and filled.password is not null
      and length(filled.password) > 0
  );

-- Sign-in compares the lowercased address. Repeat the fold for rows that
-- appeared after 0007 (skipped when two casings collided).
update "user" as u
set email = lower(u.email)
where u.email <> lower(u.email)
  and not exists (
    select 1 from "user" other
    where other.id <> u.id and lower(other.email) = lower(u.email)
  );

-- Small display copies. Original uploads stay in data_b64 and are not sent to the feed.
alter table media add column if not exists card_b64 text;
alter table media add column if not exists view_b64 text;
alter table profile_images add column if not exists view_b64 text;

